import java.util.Optional;

public class Main {
    static Optional<String> find(String key) {
        if (key.equals("{w}")) {
            return Optional.of("{v}");
        }
        return Optional.empty();
    }

    static void show(Optional<String> box, String label) {
        System.out.println(label + box.orElse("啥也没有"));
    }

    public static void main(String[] args) {
        show(find("{w}"), "找到的：");
        show(find("别的"), "兜底的：");
    }
}
